/**
 * Help text that replaces PyMOL's for this runtime, by setting name (the
 * help column only; name, type and default stay generated). A value a .pse
 * brings in is never rewritten. Each key must name exactly one generated row
 * (`pymolSettingsData.test.ts`).
 */
export const SETTING_HELP_OVERRIDES: Readonly<Record<string, string>> = {
  // The runtime ships only the DejaVu Sans faces; any other id draws as Sans (PT-9554).
  label_font_id: '(integer, default: 5) Label font: 5 = Sans, 6 = Sans Oblique, 7 = Sans Bold, 8 = Sans Bold Oblique; any other id is drawn as Sans.',
}

/** `rows` with each named row's help replaced by `overrides`; every other row is the same object. */
export function withHelpOverrides(rows: readonly SettingRow[], overrides: Readonly<Record<string, string>>): readonly SettingRow[] {
  return rows.map(row => (Object.prototype.hasOwnProperty.call(overrides, row[0]) ? ([row[0], row[1], row[2], overrides[row[0]]] as const) : row))
}

/** The settings the dialog lists: the generated rows with `SETTING_HELP_OVERRIDES` applied. */
export const PYMOL_SETTINGS: readonly SettingRow[] = withHelpOverrides(GENERATED_SETTINGS, SETTING_HELP_OVERRIDES)
